import{_ as t,o as a,c as i,ag as s}from"./chunks/framework.CxkNbRKf.js";const h=JSON.parse('{"title":"Codelists","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/codelists.md","filePath":"admin-guide/web-ui/codelists.md","lastUpdated":1786379412000}'),o={name:"admin-guide/web-ui/codelists.md"};function l(r,e,n,d,c,u){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="codelists" tabindex="-1">Codelists <a class="header-anchor" href="#codelists" aria-label="Permalink to &quot;Codelists&quot;">​</a></h1><p>Codelists are controlled vocabularies — standardized lists of codes and labels — used to ensure consistent classification across catalog entries. They can be linked to <a href="./data-structures.html">data structures</a> to provide valid values for categorical variables.</p><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: Codelists list view showing available codelists with name, agency, version, and status</em></p></div><h2 id="accessing-codelists" tabindex="-1">Accessing codelists <a class="header-anchor" href="#accessing-codelists" aria-label="Permalink to &quot;Accessing codelists&quot;">​</a></h2><p>Go to <strong>Settings → Codelists</strong> in the administrator menu.</p><h2 id="creating-a-codelist" tabindex="-1">Creating a codelist <a class="header-anchor" href="#creating-a-codelist" aria-label="Permalink to &quot;Creating a codelist&quot;">​</a></h2><ol><li>Click <strong>Add codelist</strong>.</li><li>Fill in: <ul><li><strong>Agency</strong> — the organization responsible for the codelist (default: NADA)</li><li><strong>Name</strong> — a unique identifier for the codelist</li><li><strong>Version</strong> — semantic version number (e.g., <code>1.0.0</code>)</li></ul></li><li>Click <strong>Save</strong>.</li></ol><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: Create codelist form</em></p></div><h2 id="managing-items" tabindex="-1">Managing items <a class="header-anchor" href="#managing-items" aria-label="Permalink to &quot;Managing items&quot;">​</a></h2><p>Each codelist contains a set of code–label pairs. To manage items:</p><ol><li>Open a codelist from the list.</li><li>Click <strong>Items</strong>.</li><li>Add, edit, or delete items. Each item has: <ul><li><strong>Code</strong> — the machine-readable value</li><li><strong>Label</strong> — the human-readable description</li><li><strong>Description</strong> — optional extended description</li></ul></li></ol><div class="info custom-block"><p class="custom-block-title">Screenshot</p><p><em>Add screenshot: Codelist items editor</em></p></div><h2 id="managing-groups" tabindex="-1">Managing groups <a class="header-anchor" href="#managing-groups" aria-label="Permalink to &quot;Managing groups&quot;">​</a></h2><p>Items can be organized into hierarchical groups. Groups are useful for large codelists where items benefit from categorization.</p><h2 id="status-workflow" tabindex="-1">Status workflow <a class="header-anchor" href="#status-workflow" aria-label="Permalink to &quot;Status workflow&quot;">​</a></h2><p>Codelists follow a publication status progression:</p><table tabindex="0"><thead><tr><th>Status</th><th>Description</th></tr></thead><tbody><tr><td>Draft</td><td>Under development, not yet published</td></tr><tr><td>Review</td><td>Submitted for review</td></tr><tr><td>Published</td><td>Active and available for use</td></tr><tr><td>Deprecated</td><td>Being phased out — still usable but flagged</td></tr><tr><td>Archived</td><td>No longer in use</td></tr></tbody></table><p>Only <strong>Published</strong> codelists can be linked as value domains in data structures.</p><h2 id="multi-language-support" tabindex="-1">Multi-language support <a class="header-anchor" href="#multi-language-support" aria-label="Permalink to &quot;Multi-language support&quot;">​</a></h2><p>Codelist item labels and descriptions can be defined in multiple languages. Select the target language when editing an item to add translations.</p>',20)])])}const p=t(o,[["render",l]]);export{h as __pageData,p as default};
